// Mounted check for async callbacks (replaces State.mounted).
bool isMounted() => context.mounted;

void onSeekFeedbackUpdate(int targetMs, int durationMs, double fraction) {
  if (!isLinux) return;
  seekFeedbackClearTimer.value?.cancel();
  seekFeedback.value = (targetMs: targetMs, durationMs: durationMs, fraction: fraction);
}

void onSeekFeedbackEnd() {
  if (!isLinux) return;
  seekFeedbackClearTimer.value?.cancel();
  // Give the harness a short post-gesture window to capture the preview
  // before it clears, while still satisfying "clear after gesture".
  seekFeedbackClearTimer.value = Timer(const Duration(milliseconds: 250), () {
    if (!isMounted()) return;
    seekFeedback.value = null;
  });
}

